E=json.loads((Path(__file__).resolve().parents[1]/'shared/library-edition.json').read_text(encoding='utf8'))

def clean_en(value):
 return re.sub(r'(?<=[a-z])(?=\d)|(?<=NOTE)(?=\d)',' ',value)

def assignments(n,m):
 if m==3:return {2:['1/Plan','2/Check'],3:['1/Plan','2/Write','3/Check'],4:['1','2','3','Write/Check'],5:['1','2','3','Repeat','Write/Check'],6:['1','2','3','Repeat','Write','Check']}[n]
 base={2:['Read/Write','Move/Check'],3:['Read','Move','Check/Write'],4:['Read','Move','Check','Write'],5:['Read','Read','Move','Check','Write'],6:['Read','Read','Move','Move','Check','Write']}[n]
 return [base[(i-m+1)%n] for i in range(n)]

