def guide_content(locale):
 # Defined below with operation and adult-reference pages kept separate.
 return _guide(locale)

def _guide(locale):
 zh=locale=='zh';T=lambda en,cn:cn if zh else clean_en(en)
 def team(n):
  def tr(s):
   if not zh:return s
   for a,b in [('Read','朗读'),('Write','记录'),('Move','操作'),('Check','核查'),('Plan','商议'),('Repeat','复述')]:s=s.replace(a,b)
   return s
  return grid([T('Seat','座位')]+[T(f'M{m}',f'第{m}关') for m in range(1,6)],[[str(i+1)]+[tr(assignments(n,m)[i]) for m in range(1,6)] for i in range(n)],row_height=28)
 guide=[
 P(T('Teacher Guide / start here','教师指南／从这里开始'),T('Adult only. 14 player pages and19 guide pages per paper size.','仅供成人。每种纸型玩家14页、教师19页。'),
  box(T('What pupils make','学生会完成什么'),T('A five-mission story repair: find a book, sequence four narrative leaves, combine three witness sources, make a route record and author a final page, then read and correct a misreading. The sequence is fixed; the ending has factual constraints and accepts different wording.','五关故事修复：找书、排列四段叙事、结合三份见证、制作路线记录并续写末页，最后朗读和纠错。故事顺序固定，结尾须符合事实，但允许不同表达。')),
  box(T('Prepare first','开始前准备'),T('Choose whole-sheet or optional leaf mode on page2. Use page3 to stage materials and pages4–5 to announce each seat’s task. Give players1–3 only. Read only marked story boxes aloud; the next page after each operation page is a private adult reference.','按第2页选择整页或摆页玩法。按第3页分堆，按第4至5页告知座位任务。开始只发玩家第1至3页。只朗读标明的故事框，各关操作页后紧接的是成人核对页，不展示给学生。')),
  text(T('Paper, pencil and eraser are enough. An adult cuts three private notes and, only in leaf mode, four story leaves. No trip, book purchase, glue or device is needed.','只需纸、铅笔、橡皮。成人剪三张独立见证卡；只有摆页玩法另剪四段故事。不需外出、买书、胶水或设备。'))),
 P(T('Print and cutting inventory','打印与裁剪清单'),T('One paper size per crew, single-sided at100% Actual size. Do not scale to fit.','每组使用同一种纸型，单面、100%实际大小打印，不缩放适应纸张。'),
  grid([T('Crews','组数'),T('Player sheets','玩家纸张'),T('With one full guide','另印一本完整指南')],[[T('1 crew','1组'),'14','14+19=33'],[T('6 crews /35 pupils','6组／35人'),'6×14=84','84+19=103'],[T('7 crews /35 pupils','7组／35人'),'7×14=98','98+19=117']],ratios=[.25,.33,.42],row_height=38),
  box(T('Whole-sheet mode /3 pieces per crew','整页玩法／每组3件'),T('Keep roles, progress, story leaves, route record and authoring sheets whole. Cut only the THREE page10 witness notes. Six crews need18 notes; seven crews21. This mode still requires adult cutting.','角色、进度、故事页、路线记录和续写页全部整页保留，只剪玩家第10页三张见证卡。6组剪18张，7组剪21张。这种玩法仍需要成人裁剪。')),
  box(T('Optional leaf mode /7 pieces per crew','摆页玩法／每组7件'),T('Cut the same three notes plus the four dashed leaves on pages7–8. Place leaves on the table beside page6; small slots hold letters, not full cards. Six crews42 pieces; seven crews49. No role or route-sheet cuts.','三张见证卡以外，再剪第7至8页四段故事，共7件。故事卡摆在第6页旁的桌上，小格只填字母。6组共42件，7组49件。不剪角色页或路线页。')),
  text(T('The guide may be read on screen. Player11 is the paper used in the story plan; no extra blank-paper prop is required. Try one sheet in monochrome first: shape and dot count carry the clues.','教师指南可在屏幕阅读。玩家第11页就是落实方案所用的纸，不必另外准备空白纸。整套打印前可先试印一页黑白，线索靠形状和点数区分。'))),
 P(T('Stage, retain and hand over','分堆、保留与交接'),T('Keep this guide and later missions with the teacher.','本指南和后续关卡均由教师保管。'),
  grid([T('Stage','阶段'),T('Give','发放'),T('Retain','保留')],[[T('Start','开始'),'1–3',T('Roles/progress whole','角色、进度整页')],['1','4',T('Marks and shelf result','图案与架位结果')],['2','5–8',T('Opening/map/order/all four leaves','开篇、原图、顺序和四段故事')],['3','9+10',T('Facts/plan and three separate notes','事实、方案及三张分别发的卡')],['4','11–12',T('Completed route and authored ending','完成的路线与续写')],['5','13–14',T('Full story, original sources and correction','完整故事、原来源与纠正')]],ratios=[.14,.20,.66],row_height=42),
  box(T('Only after acceptance','通过后再交接'),T('Check evidence, tick Player3, announce the next seat tasks and release the next pile. Give page5 only after mission1; pages11–12 only after mission3. Never hand page10 over whole. Visitors must have finished mission4 too.','核对证据、勾玩家第3页、告知下一关座位任务，再发下一堆。第5页只在首关通过后发，第11至12页只在第三关通过后发。第10页不整张给学生，访客也必须先完成第四关。'))),
 P(T('Seat tasks /2–4 pupils','座位任务／2至4人'),T('Teacher announces tasks; students do not open this answer guide. Read/Move/Check/Write are the four page2 jobs.','教师告知任务，学生不翻答案册。朗读、操作、核查、记录对应玩家第2页四种角色。'),
  text(T('2 pupils: at mission3 each holds note1 or2; after both share, the teacher reads note3. Then both plan and check.','2人：第三关各持1或2卡，两人分享后教师读第3卡，再由两人共同商议和核查。')),team(2),text(T('3 pupils: one note each at mission3; all help plan.','3人：第三关各持一卡，分享后一起商议。')),team(3),text(T('4 pupils: three note holders and a recorder/checker at mission3.','4人：第三关三名持卡者，一名记录兼核查。')),team(4)),
 P(T('Seat tasks /5–6 pupils','座位任务／5至6人'),T('Paired jobs take turns: one acts, one checks, then swap. At the final reading everyone contributes one part.','同名搭档轮流操作与核查，最后朗读每人至少贡献一部分。'),
  text(T('5 pupils: three holders, one restates and one records/checks at mission3.','5人：第三关三人持卡、一人复述、一人记录兼核查。')),team(5),text(T('6 pupils: three holders plus separate restating, writing and checking.','6人：第三关三人持卡，另三人分别复述、记录、核查。')),team(6),
  box(T('Whole class /35 pupils','整班／35人'),T('Use five crews of six and one of five, or seven crews of five. Keep one complete bundle per crew. A waiting crew may reread issued material, never later piles. Pair visitors only after both crews finish mission4.','可分5个6人组加1个5人组，或7个5人组。每组独立一整套。等待时只重读已发页，不看后续材料。互访双方须先完成第四关。'))),
 P(T('Opening and teaching rhythm','开场与主持节奏'),T('Read story boxes only; keep adult answers private.','只读故事框，成人答案保密。'),
  box(T('Opening / read aloud','开场／可照读'),T('Welcome to the Storybook Library repair desk. A return slip has lost its title, some pages are mixed up and the final page is damaged. Find the book through its marks, follow what happened and help finish a story that fits the evidence. You can ask, pause and revise.','欢迎来到故事图书馆修复台。还书条上的书名模糊了，几页故事顺序错乱，最后一页也破损了。请根据图案找书，再循着故事和证据补好结尾。可以提问、暂停和修正。')),
  box(T('One checked stage at a time','逐关核准'),T('Read the scene, give only that mission, allow an attempt, ask for original evidence and give one hint if needed. Then pupils retry. Direct level3 hints are explicit help, not an unassisted solution. Nobody is eliminated.','读当前场景、发当前材料、让学生尝试、询问原始依据，需要时只给一条提示，再让学生重试。第三级明确是答案性帮助，不算独立推理结果，不淘汰任何人。')),
  box(T('Composition and time','续写与时间'),T('The pupils’ last page stays in the story-hour evening. A promise or plan to return a borrowed item tomorrow fits; the adult closing later confirms the next-day action. Do not force tomorrow’s event before tonight’s final line.','学生末页停留在听故事的当晚，可以交代明日归还的承诺或安排。成人结尾随后确认第二天的行动，不把明日事件硬放在当晚末句之前。')))
 ]
 stages=[
 (T('Find the book','找到故事书'),'4',T('A faded return slip lies on the desk. Two stamp features remain. Which shelf matches both?','模糊的还书条放在桌上，还留下两项印章特征。哪张架位卡同时符合？'),T('Have pupils compare every shape and dot count, point to both matches and record one code on Player4. The book title stays on Player5 until acceptance.','让学生逐张比较形状与点数、指出两项匹配，在玩家第4页记录一次架位号。通过前不展示第5页书名。'),T('L-24 matches a crescent and two dots. Shape alone leaves three candidates; two dots alone leaves two. Both are needed.','L-24同时符合月牙和两点。只看形状有三个候选，只看两点有两个候选，必须结合两项。'),[T('Which two features survived?','留下了哪两项特征？'),T('Check shape and count separately, then combine.','分开核形状和数量，再结合。'),T('L-24 matches both; point to each match.','L-24两项都符合，请逐项指出。')],T('Keep Player4. Give page5 first; read the opening before giving pages6–8.','保留玩家第4页，先发第5页。读完开篇后，再发第6至8页。')),
 (T('Restore the sequence','整理故事顺序'),'5–8',T('You found the opening. Four middle leaves are loose. Read their words to restore what happened.','你们找到了开篇，但中间四段散落了。请读原文，恢复发生的顺序。'),T('Read Player5, then all four leaves. Record letters once on Player6. Whole-sheet mode points/turns; leaf mode arranges four pieces beside it. Ask for two supporting phrases and an oral explanation of the remaining link.','先读玩家第5页，再读四段故事。顺序只写第6页一次。整页玩法指读翻页，摆页玩法把四卡排在旁边。要求两处短句依据，其余衔接口头说明。'),T('B-D-C-A: meeting with the borrowed map, before crossing, far bank, garden table. Accept paraphrased explanations that trace to the printed cause/time words. The map route is not the leaf order.','B-D-C-A：借图碰面、过桥之前、到了对岸、花园桌旁。解释可用自己的话，但要指回原文因果和时间词。地图路线不是书页顺序。'),[T('Where have they not begun crossing yet?','哪段里他们还没有开始过桥？'),T('Find before, after and the bridge-behind-them sentence.','找“过桥前”“过桥后”和“桥在身后”的句子。'),T('B-D-C-A is the order; explain each link.','顺序是B-D-C-A，再逐处解释衔接。')],T('Keep all leaves and issue9 plus the three separately dealt10 notes.','保留全部故事，发第9页及第10页分别剪发的三张卡。')),
 (T('Hear three witnesses','听取三份见证'),'9+10',T('The story has reached the garden table. Three people have left separate records. Hear them all before deciding what can happen.','故事到了花园桌旁，三个人各留了一份记录。请先听完，再商量接下来可以怎样做。'),T('Use the mission3 seat tasks. The teacher reads note3 only to a two-pupil crew after notes1/2. Listeners restate facts; record each source once on Player9, then form a plan. The task must not supply the facts before sharing.','按第三关座位任务分卡。两人时先分享1、2卡，教师再读3卡。听者复述事实，在玩家第9页各记一次，再拟方案，不提前替学生概括关键条件。'),T('The plan uses directions Kit can keep, Rowan’s duty to return the only original tomorrow, and the keeper’s paper/pencil. A drawn or written route copy uses all three. Accept different people making it and different wording; merely giving away the original, inventing a rescue, or ignoring a source does not pass.','方案须用到：小凯可随身看的指路信息、罗文明日归还唯一原图的责任、管理员准备的纸笔。画图或写地标制作一份路线记录均可；谁来制作和具体措辞可以不同。送走原图、另加救援或忽略一份来源不通过。'),[T('Has every source been heard and restated?','每份来源都已听到并复述了吗？'),T('What must your plan preserve, provide and use?','方案要保住什么、帮助谁、用到什么？'),T('Make a route copy on the available paper for Kit; Rowan keeps the original to return tomorrow.','用现成纸笔给小凯做路线记录，罗文留下原图明天归还。')],T('Only after an evidenced plan, issue11–12. Keep all three notes.','有依据的方案通过后才发第11至12页，三张原卡都保留。')),
 (T('Author the last page','补好最后一页'),'11–12',T('The damaged last page has its first and last lines. Carry out your agreed plan, then tell the missing action in between.','破损末页还留着第一句和最后一句。请落实已商定的办法，再把中间缺少的行动讲出来。'),T('Use the original Player5 map and checked Player9 plan. Player11 is the prepared paper for implementing it and may stay whole. Check the route, then let pupils author Player12. Ask neutral questions about actions and evidence, not a sentence to copy.','用玩家第5页原图和第9页方案，第11页就是落实方案的准备纸，可整页保留。先核路线，再让学生写第12页。中性询问行动与依据，不给一句让全组抄。'),T('Route: Garden table → Garden gate → River bridge → Kit’s home. Short labels or labelled drawings count. The scene gives Kit usable directions, keeps the original for return, uses the known resources and connects the surviving lines. Accept short dictation or several sentences; no fixed word count. Tomorrow may be a clear promise, not an event forced before tonight’s smile.','路线：花园桌→花园门→河桥→小凯家。短地名或带标注图画均可。片段让小凯有可用路线、原图留待归还、用到已知资源，能接上保留句。接受简短口述或数句话，不定字数。明日可写成明确承诺，不强塞在当晚笑起来之前。'),[T('Trace each stop to the original map.','把每一站指回原图。'),T('Read your accepted plan and three facts; does the scene carry them out?','读已核准的方案和三条事实，片段落实了吗？'),T('Example only: The keeper offered paper and a pencil. Kit wrote the route. Rowan said, “I will return the original tomorrow.” Kit kept the new directions. Other wording and a different copier may pass.','示范强提示：管理员拿来纸笔，小凯记好路线。罗文说：“我明早把原图还回去。”小凯收好新的路线记录。换人物制作或换说法也可通过。')],T('Read the ending, then issue13–14. Pair only with a crew that also finished mission4.','读通结尾后发第13至14页，只与也完成第四关的小组互访。')),
 (T('Read and repair a misreading','朗读并纠正误读'),'13–14',T('The story has a last page again. Read it to a ready visitor, then test the visitor’s claim against your evidence.','故事又有最后一页了。请读给准备好的访客，再用证据核查访客的说法。'),T('Use Player13’s reading sequence and the crew’s own Player6 order, not the printed page order. With whole sheets, point and turn. Keep each crew’s work separate. A single crew uses the teacher visitor. Ask for the mistaken fact and original sources; recheck repairs.','按玩家第13页和本组第6页顺序读，不按印刷页码直读。整页时指认并翻页，两组作品分开；单组由教师当访客。询问错在哪里、原依据是什么，修正后再核。'),T('Kit keeps the route COPY/directions, while Rowan retains the ORIGINAL to return tomorrow. The correction may be spoken, written or dictated with the original note and completed work pointed out. Check all four Player14 items and one contribution each. Evidence and coherent facts matter, not grammar or drawing polish.','小凯带走新制作的路线记录，罗文保管原图并在明日归还。可口述、书写或代写纠正，但须指出原卡和作品。核玩家第14页四项及每人贡献，依据和事实连贯性重要，不按语法、画工评分。'),[T('Which part of the visitor’s claim conflicts with your story?','访客哪部分说法与本组故事不符？'),T('Compare the witness note about the borrowed object with your finished route record.','把关于借用物的原卡与完成的路线记录对照。'),T('Correct it: Kit keeps new directions; Rowan keeps and returns the borrowed original. Explain with sources.','改为：小凯收好新路线记录，罗文保管并按期归还借来的原图；再指出来源。')],T('Tick Player3 only after repairs pass, then read Guide19.','修正通过后勾玩家第3页，再读教师第19页结尾。'))
 ]
 for n,(title,give,scene,action,answer,hints,handover) in enumerate(stages,1):
  guide.append(P(T(f'Mission{n} / teacher actions',f'第{n}关／教师操作'),title,
   box(T('Prepare and give','准备与发放'),T('Player pages ','玩家第')+give+T(' only; keep later piles private.','页，后续堆继续保密。')),
   box(T('Story / read aloud','故事／可照读'),scene),box(T('Lead without supplying the result','引导，不代答'),action),
   box(T('Every pupil contributes','每人有贡献'),T('Invite reading, pointing, moving, restating, writing or dictation. Ask for a second check. The next page is adult-only acceptance help, not a pupil handout.','邀请朗读、指认、操作、复述、书写或口述，并请另一人核查。下一页是成人核对帮助，不发学生。'))))
  guide.append(P(T(f'Mission{n} / adult reference',f'第{n}关／成人核对'),T('Use after the crew attempts the task. Keep all answers private.','小组尝试后使用，答案不展示。'),
   box(T('Acceptance and explanation','通过标准与说明'),answer),box(T('Graduated hints /3 gives explicit help','分级提示／第三级为答案性强提示'),'<br/>'.join(f'{i}. {v}' for i,v in enumerate(hints,1))),box(T('Keep and hand over','保留与交接'),handover)))
 guide += [
 P(T('Hosting quick reference','主持速查／不含解答内容'),T('Use after preparation; original facts remain on player sheets.','完成准备后使用，具体原事实保留在玩家材料上。'),
  *[box(T(f'{i} / ','第'+str(i)+'关／')+title,T('Give Player','发玩家')+give+T('. Check evidence on the original task; private acceptance reference: Guide','. 核对原任务上的证据；成人答案见教师第')+str(6+i*2)+T('. Then follow the handover.','页，再按交接要求继续。')) for i,(title,give,*_) in enumerate(stages,1)]),
 P(T('Support, pause and visitor handoff','帮助、暂停与访客交接'),T('Same evidence requirements in both cutting modes.','两种裁剪方式的证据要求相同。'),
  box(T('Reading and writing support','阅读与书写支持'),T('Read one sentence at a time; invite pointing or restating. A partner or adult may record exactly the pupil’s idea. Short labelled drawings count. Older readers may explain why another order fails or improve transitions, without new factual requirements.','一次读一句，请学生指认或复述。伙伴或成人可以照学生意思代写，短标注绘图也算。阅读熟练者可解释另一顺序为何不通，或润色衔接，不另加事实门槛。')),
  box(T('Pause or missing material','暂停或丢件'),T('Store checked and unfinished issued work by crew, with progress page3. Teacher keeps unopened piles. Reprint the labelled missing page; never invent a replacement clue. Resume the unfinished step using the same mode.','按组保存已核准和正在做的材料及第3页进度，未发堆留教师处。丢件补印标注页，不临时编线索。使用原裁剪方式继续未完成步骤。')),
  box(T('Qualified visitors','访客须已准备好'),T('Both crews must have finished mission4 before visiting. Ask one group to listen, check an original source and ask one evidence question; do not copy each other’s papers. The teacher can visit any single crew.','互访双方先完成第四关。请访客听故事、查一处原来源、问一个证据问题，不互抄作品。只有一组时教师担任访客。'))),
 P(T('Closing / after all checks','结尾／全部核查通过后'),T('Do not give pupils this adult page.','本页由成人保管，不提前发给学生。'),
  box(T('Read after acceptance','通过后可照读'),T('The reading crew repaired the story. Kit followed the new route directions home. The next morning, Rowan returned the original map as promised. The library can share the complete story again. Thank you for listening, explaining and helping one another.','阅读小组补好了故事。小凯照着新路线记录回到家。第二天早晨，罗文按约归还了原始地图。图书馆又可以分享完整的故事了。谢谢你们认真倾听、解释和互相帮助。')),
  box(T('One contribution each','每人说一次贡献'),T('Invite one read passage, checked mark, source fact, ordering reason, authored sentence or corrected claim from each pupil. Do not rank crews by speed or writing length.','请每人说或指出一次贡献：读过的段落、核过的图案、原事实、排序理由、自写句子或纠正过的说法。不按速度和写作长短排名。')),
  box(T('Keep and reset','保留与重置'),T('Keep the repaired story if desired. Count three notes in whole-sheet mode or seven pieces in leaf mode. Keep roles, progress, original map and route sheet whole. Reprint blank task pages for another play; the facts and solution remain the same even when wording changes.','可以保留修复后的故事。整页玩法核三张卡，摆页玩法核七件。角色、进度、原图和路线页均整页保留。重玩时补印空白任务页；表达可以变化，但事实与主要解法相同。')))
 ]
 return guide
